func testEncryptedAuthKey(t *testing.T, salt, hostname, authKey string) string {
	t.Helper()
	enc, err := EncryptAuthKey(AuthKeyCipherKey(salt), hostname, authKey)
	if err != nil {
		t.Fatalf("EncryptAuthKey: %v", err)
	}
	return enc
}

// authKeyVector is shared with the dashboard's WebCrypto implementation
// (web/monitor/src/authkeyCrypto.ts); a change here means links generated by
// one side stop opening on the other.
var authKeyVector = struct {
	salt, hostname, authKey, nonceHex, keyHex, value string
}{
	salt:     "demo-salt",
	hostname: "macbook-air",
	authKey:  "tskey-auth-kDEMO1CNTRL-VirtualKeyNotReal123",
	nonceHex: "000102030405060708090a0b",
	keyHex:   "e107f212b4340f98825f97abcfe1f71775ef61ad57ba3fe2aa5665ca002e1e6a",
	value:    "v1.AAECAwQFBgcICQoL0_ILKreXq9w2GKDIxYxeO4qhzEG-a9h2nvOEUAcYA98LmNF84sUnMR1J2xTD2afxdTgleotLCT_1hYw",
}

func TestAuthKeyKnownAnswer(t *testing.T) {
	v := authKeyVector
	key := AuthKeyCipherKey(v.salt)
	if got := hex.EncodeToString(key); got != v.keyHex {
		t.Fatalf("AuthKeyCipherKey = %s, want %s", got, v.keyHex)
	}
	// The salt is trimmed exactly as the URL token derivation trims it.
	if got := hex.EncodeToString(AuthKeyCipherKey(" " + v.salt + "\n")); got != v.keyHex {
		t.Fatalf("untrimmed salt: AuthKeyCipherKey = %s", got)
	}
	nonce, err := hex.DecodeString(v.nonceHex)
	if err != nil {
		t.Fatal(err)
	}
	got, err := sealAuthKey(key, nonce, v.hostname, v.authKey)
	if err != nil {
		t.Fatalf("sealAuthKey: %v", err)
	}
	if got != v.value {
		t.Fatalf("sealed = %q, want %q", got, v.value)
	}
	plain, err := DecryptAuthKey(key, v.hostname, v.value)
	if err != nil || plain != v.authKey {
		t.Fatalf("DecryptAuthKey = %q, %v", plain, err)
	}
}

// The key derivation is the standard library's HKDF; pin it to RFC 5869 test
// case 3 (empty salt and info) so the zero-salt convention the WebCrypto side
// relies on is unambiguous.
func TestAuthKeyKDFMatchesRFC5869(t *testing.T) {
	ikm := bytes.Repeat([]byte{0x0b}, 22)
	okm, err := hkdf.Key(sha256.New, ikm, nil, "", 42)
	if err != nil {
		t.Fatal(err)
	}
	const want = "8da4e775a563c18f715f802a063c5a31b8a11f5c5ee1879ec3454e5f3c738d2d9d201395faa4b61a96c8"
	if got := hex.EncodeToString(okm); got != want {
		t.Fatalf("OKM = %s, want %s", got, want)
	}
}

func TestAuthKeyCipherKeyFileRoundTrip(t *testing.T) {
	file := AuthKeyCipherKeyFile(authKeyVector.salt)
	if string(file) != authKeyVector.keyHex+"\n" {
		t.Fatalf("key file = %q", file)
	}
	key, err := ParseAuthKeyCipherKeyFile(file)
	if err != nil || hex.EncodeToString(key) != authKeyVector.keyHex {
		t.Fatalf("ParseAuthKeyCipherKeyFile = %x, %v", key, err)
	}
	for _, bad := range []string{"", "\n", "zz", authKeyVector.keyHex[:62] + "\n", authKeyVector.keyHex + "00\n"} {
		if key, err := ParseAuthKeyCipherKeyFile([]byte(bad)); err == nil {
			t.Errorf("ParseAuthKeyCipherKeyFile(%q) = %x, want error", bad, key)
		}
	}
}

func TestAuthKeyRoundTrip(t *testing.T) {
	key := AuthKeyCipherKey("salt")
	for _, authKey := range []string{"tskey-x", "tskey-auth-kAbC123CNTRL-XyZ_789", "tskey-" + strings.Repeat("a", 200)} {
		enc, err := EncryptAuthKey(key, "nas", authKey)
		if err != nil {
			t.Fatalf("EncryptAuthKey: %v", err)
		}
		if !encryptedAuthKeyRE.MatchString(enc) {
			t.Fatalf("encryption of a %d-byte key (%d chars) fails the shape check", len(authKey), len(enc))
		}
		got, err := DecryptAuthKey(key, "nas", enc)
		if err != nil || got != authKey {
			t.Fatalf("round trip of %q = %q, %v", authKey, got, err)
		}
	}
	// A fresh nonce per encryption: the same key never yields the same link.
	if testEncryptedAuthKey(t, "salt", "nas", "tskey-a") == testEncryptedAuthKey(t, "salt", "nas", "tskey-a") {
		t.Fatal("two encryptions produced the same value")
	}
}

func TestEncryptAuthKeyRejectsInvalidInput(t *testing.T) {
	key := AuthKeyCipherKey("salt")
	for _, authKey := range []string{"not-a-key", "tskey-", "tskey-a b", "tskey-" + strings.Repeat("a", 201)} {
		if enc, err := EncryptAuthKey(key, "nas", authKey); err == nil {
			t.Errorf("EncryptAuthKey(%q) = %q, want error", authKey, enc)
		}
	}
	if enc, err := EncryptAuthKey(key[:16], "nas", "tskey-a"); err == nil {
		t.Errorf("EncryptAuthKey with a 16-byte key = %q, want error", enc)
	}
}

func TestDecryptAuthKeyRejects(t *testing.T) {
	const authKey = "tskey-auth-SECRETVALUE123"
	key := AuthKeyCipherKey("salt")
	enc := testEncryptedAuthKey(t, "salt", "nas", authKey)
	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(enc, authKeyValuePrefix))
	if err != nil {
		t.Fatal(err)
	}
	reencode := func(b []byte) string { return authKeyValuePrefix + base64.RawURLEncoding.EncodeToString(b) }
	tampered := func(i int) string {
		b := bytes.Clone(raw)
		b[i] ^= 0x01
		return reencode(b)
	}
	// A non-key plaintext that still authenticates must fail the format check.
	aead, err := authKeyAEAD(key)
	if err != nil {
		t.Fatal(err)
	}
	nonce := make([]byte, authKeyNonceSize)
	notAKey := reencode(aead.Seal(bytes.Clone(nonce), nonce, []byte("hello, world"), []byte("nas")))

	cases := []struct {
		name, salt, hostname, value string
	}{
		{"wrong salt", "other-salt", "nas", enc},
		{"empty salt", "", "nas", enc},
		{"wrong hostname", "salt", "nas-2", enc},
		{"hostname case", "salt", "NAS", enc},
		{"tampered nonce", "salt", "nas", tampered(0)},
		{"tampered ciphertext", "salt", "nas", tampered(authKeyNonceSize + 1)},
		{"tampered tag", "salt", "nas", tampered(len(raw) - 1)},
		{"truncated", "salt", "nas", reencode(raw[:len(raw)-1])},
		{"truncated encoding", "salt", "nas", enc[:len(enc)-1]},
		{"no version", "salt", "nas", strings.TrimPrefix(enc, authKeyValuePrefix)},
		{"unknown version", "salt", "nas", "v2." + strings.TrimPrefix(enc, authKeyValuePrefix)},
		{"padded", "salt", "nas", authKeyValuePrefix + base64.URLEncoding.EncodeToString(raw)},
		{"standard alphabet", "salt", "nas", strings.NewReplacer("-", "+", "_", "/").Replace(enc) + "+/"},
		{"garbage", "salt", "nas", authKeyValuePrefix + strings.Repeat("A", 80)},
		{"too long", "salt", "nas", authKeyValuePrefix + strings.Repeat("A", 313)},
		{"empty", "salt", "nas", ""},
		{"plaintext key", "salt", "nas", authKey},
		{"plaintext non-key", "salt", "nas", notAKey},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := DecryptAuthKey(AuthKeyCipherKey(tc.salt), tc.hostname, tc.value)
			if err == nil {
				t.Fatalf("decrypted to %q", got)
			}
			if got != "" || strings.Contains(err.Error(), "SECRETVALUE") || (tc.value != "" && strings.Contains(err.Error(), tc.value)) {
				t.Fatalf("error leaks the value: %q, %v", got, err)
			}
		})
	}
	if got, err := DecryptAuthKey(key[:16], "nas", enc); err == nil {
		t.Fatalf("DecryptAuthKey with a 16-byte key = %q", got)
	}
}

func TestDecryptedAuthKeyFeedsApplyTailscale(t *testing.T) {
	enc := testEncryptedAuthKey(t, "salt", testClientOpts.Hostname, testClientOpts.AuthKey)
	opts, ok, err := ParseTailscaleQuery(map[string][]string{
		"tailscale": {"client"}, "hostname": {testClientOpts.Hostname}, "authkey": {enc},
	})
	if err != nil || !ok {
		t.Fatalf("ParseTailscaleQuery = %v, %v", ok, err)
	}
	if opts.AuthKey != "" {
		t.Fatal("ParseTailscaleQuery set a plaintext AuthKey")
	}
	if opts.AuthKey, err = DecryptAuthKey(AuthKeyCipherKey("salt"), opts.Hostname, opts.EncryptedAuthKey); err != nil {
		t.Fatalf("DecryptAuthKey: %v", err)
	}
	if opts.AuthKey != testClientOpts.AuthKey {
		t.Fatalf("AuthKey = %q", opts.AuthKey)
	}
	if _, err := ApplyTailscale(ProfileSingBox, []byte(singBoxFixture), opts); err != nil {
		t.Fatalf("ApplyTailscale: %v", err)
	}
}
